CustomField.formula:
IF(
    AND(
        IsCheckout__c = TRUE,
        NOT(ISBLANK(Logged_Out_At__c)),
        NOT(ISBLANK(Logged_At__c))
    ),
    LPAD(
        TEXT(
            FLOOR(
                (Logged_Out_At__c - Logged_At__c) * 24
            )
        ),
        2,
        "0"
    )
    & ":" &
    LPAD(
        TEXT(
            FLOOR(
                MOD(
                    (Logged_Out_At__c - Logged_At__c) * 1440,
                    60
                )
            )
        ),
        2,
        "0"
    ),
    NULL
)
